document.querySelectorAll('.prov').forEach(p=>p.onclick=()=>document.getElementById('mapInfo').textContent='Wilayah '+p.dataset.name+': Tari khas akan tampil di halaman detail.');const c=document.getElementById('countdown');if(c){const t=new Date(c.dataset.date).getTime();setInterval(()=>{const d=t-Date.now();if(d<=0){c.textContent='Hari Tari Nasional telah tiba!';return;}const day=Math.floor(d/864e5),hr=Math.floor((d%864e5)/36e5);c.textContent=day+' hari '+hr+' jam lagi';},1e3)}const s=document.getElementById('searchTari');if(s){s.addEventListener('input',async()=>{const r=await fetch('?r=tari&ajax=1&q='+encodeURIComponent(s.value));const data=await r.json();document.getElementById('list').innerHTML=data.map(x=>`<div class='col-md-3'><div class='card mb-3'><img loading='lazy' class='card-img-top' src='${x.gambar||'assets/img/default.webp'}'><div class='card-body'><h6>${x.nama_tari}</h6></div></div></div>`).join('');});}
